validator:
function validate(input) {
  const [{ Product = [], Sales = [] }] = input;
  const products = new Set(), names = new Set();
  for (const [id, name] of Product) {
    if (id === null) return 'Every product needs a product_id.';
    if (products.has(id)) return `product_id ${id} appears twice in Product.`;
    products.add(id);
    names.add(name);
  }
  if (!names.has('S8') || !names.has('iPhone')) return "Product must contain products named 'S8' and 'iPhone'.";
  for (const [seller, product, buyer, date] of Sales) {
    if (!products.has(product)) return `A sale names unknown product ${product}.`;
    if (seller === null || buyer === null) return 'Every sale needs a seller_id and a buyer_id.';
    if (typeof date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return `sale_date ${date} must be a YYYY-MM-DD date.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const catalog = [['S8', 1000], ['iPhone', 1400], ['G4', 800], ['Pixel', 900], ['Note', 1100]];
  // Shuffle product ids so S8 and iPhone do not always have ids 1 and 3.
  const ids = [1, 2, 3, 4, 5, 6, 7];
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const kept = small ? 2 + Math.floor(rand() * 2) : catalog.length;
  const Product = catalog.slice(0, kept).map(([name, unit], i) => [ids[i], name, unit]);
  const Sales = [];
  const buyers = small ? 4 : 600, count = small ? Math.floor(rand() * 9) : 2000;
  for (let i = 0; i < count; i++) {
    // Repeat an earlier sale now and then, since Sales has no key.
    if (Sales.length && rand() < 0.1) { Sales.push([...Sales[Math.floor(rand() * Sales.length)]]); continue; }
    const [product, , unit] = Product[Math.floor(rand() * Product.length)];
    const quantity = 1 + Math.floor(rand() * 3);
    const day = String(1 + Math.floor(rand() * 28)).padStart(2, '0'), month = String(1 + Math.floor(rand() * 6)).padStart(2, '0');
    Sales.push([1 + Math.floor(rand() * 3), product, 1 + Math.floor(rand() * buyers), `2019-${month}-${day}`, quantity, quantity * unit]);
  }
  return [{ Product, Sales }];
}
